(function(root){
function assess(p){const n=k=>Number(p[k]),yes=k=>p[k]==='Yes';const required=['Age (years)','Systolic BP (mmHg)','Burden of illness','COPD','Cancer category','Previous fungal infection','Dehydration needing IV fluids','Setting at fever onset'];if(required.some(k=>p[k]===undefined||p[k]===null||p[k]===''))return{score:null,risk:'Unknown',flags:['Incomplete assessment']};const score=({'None/mild':5,'None/mild symptoms':5,'Mild':5,'None':5,'Moderate':3,'Severe':0}[p['Burden of illness']]??null);if(score===null)return{score:null,risk:'Unknown',flags:['Unrecognized symptom burden']};let total=score+(n('Systolic BP (mmHg)')>90?5:0)+(!yes('COPD')?4:0)+(p['Cancer category']==='Solid tumour'||!yes('Previous fungal infection')?4:0)+(!yes('Dehydration needing IV fluids')?3:0)+(p['Setting at fever onset']==='Outpatient'?3:0)+(n('Age (years)')<60?2:0);let flags=[];if(p['Setting at fever onset']==='Inpatient')flags.push('Inpatient at fever onset (workbook pathway rule)');for(const k of ['Mucositis grade 3–4','Pneumonia / complex infection','Catheter infection','Expected ANC <0.1 for ≥7 days','AST/ALT >5× ULN','New confusion / neuro change'])if(yes(k))flags.push(k);if(n('Systolic BP (mmHg)')<90)flags.push('Hypotension');if(p['CrCl (mL/min)']!==null&&n('CrCl (mL/min)')<30)flags.push('CrCl <30: review renal function');return{score:total,risk:total<21||flags.length?'High':'Low',flags};}
root.assess=assess;if(typeof module!=='undefined')module.exports={assess};
})(typeof window==='undefined'?globalThis:window);
